private fun svg(name: String, vw: Float, vh: Float, d: String): ImageVector =
    ImageVector.Builder(name, vw.dp, vh.dp, vw, vh).also { b ->
        b.addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.White))
    }.build()

